JS_WRAPPER = r"""
function cornerCompare(payloadText) {
  const payload = JSON.parse(payloadText);
  const candidates = payload.candidates;
  const counts = {};
  for (const c of candidates) counts[c.label]=(counts[c.label]||0)+1;
  const unique = candidates.every(c => ORDER.includes(c.label) && counts[c.label]===1 && c.points.length>=4);
  const runValidation = payload.validate && unique;
  const ptsByLabel = {}, c2Map = {};
  if(runValidation) for(const c of candidates) {
    ptsByLabel[c.label]=c.points; c2Map[c.label]=(c.label==='C2');
  }
  const fixed1 = runValidation ? validateAndFix('v1',ptsByLabel,c2Map,{frac:0.30}) : null;
  const fixed2 = runValidation ? validateAndFix('v2',ptsByLabel,c2Map,{frac:0.30}) : null;
  const reason = !payload.validate ? 'validation_disabled' : unique ? 'validated' : 'direct_duplicate_or_unsupported_labels';
  return JSON.stringify(candidates.map(c => ({
    candidate_index:c.candidate_index,label:c.label,validation:reason,
    v1:fixed1 ? fixed1[c.label] : endplateA(c.points,c.label==='C2',false),
    v2:fixed2 ? fixed2[c.label] : endplateB(c.points,c.label==='C2',false,0.30)
  })));
}
"""
js_context.eval(JS_WRAPPER)
js_corner_compare = js_context.get('cornerCompare')
